const staticData = getWorkflowStaticData('global');
if (!staticData.postedVideoIds) staticData.postedVideoIds = [];

const results = [];
for (const item of $input.all()) {
  const link = item.json.link || '';
  const m = link.match(/v=([a-zA-Z0-9_-]{6,})/);
  const videoId = m ? m[1] : null;
  if (!videoId) continue;
  if (staticData.postedVideoIds.includes(videoId)) continue;

  const rawDesc = item.json.contentSnippet || item.json.content || '';
  const description = rawDesc.replace(/\s+/g, ' ').trim().slice(0, 200);

  results.push({
    json: {
      videoId,
      title: item.json.title || '',
      link,
      description,
      pubDate: item.json.pubDate || '',
    },
  });
}
return results;

const resp = $input.first().json;
const rawBase64 = (resp.content || '').replace(/\n/g, '');
const fileSha = resp.sha;

const videoId = $('Filter New Videos').item.json.videoId;
const title = $('Filter New Videos').item.json.title;
const description = $('Filter New Videos').item.json.description;
const pubDate = $('Filter New Videos').item.json.pubDate;
const dateStr = pubDate ? new Date(pubDate).toISOString().slice(0, 10) : '';

const decoded = Buffer.from(rawBase64, 'base64').toString('utf-8');

const esc = (s) => (s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");

const newEntry = `  {\n    id: '${esc(videoId)}',\n    title: '${esc(title)}',\n    date: '${dateStr}',\n    description: '${esc(description)}',\n  },\n`;

const marker = 'const videos = [';
const idx = decoded.indexOf(marker);
if (idx === -1) {
  throw new Error('找不到 const videos = [ 標記，videos.astro 結構可能已變更，要人工檢查');
}
const insertPos = idx + marker.length;
const updated = decoded.slice(0, insertPos) + '\n' + newEntry + decoded.slice(insertPos);

const newContentBase64 = Buffer.from(updated, 'utf-8').toString('base64');
const branchName = `videos/auto-${videoId}`;

return [{
  json: {
    newContentBase64,
    fileSha,
    branchName,
    videoId,
    title,
  },
}];

const staticData = getWorkflowStaticData('global');
if (!staticData.postedVideoIds) staticData.postedVideoIds = [];

for (const item of $input.all()) {
  const videoId = $('Filter New Videos').item.json.videoId;
  if (videoId && !staticData.postedVideoIds.includes(videoId)) {
    staticData.postedVideoIds.push(videoId);
  }
}
if (staticData.postedVideoIds.length > 500) {
  staticData.postedVideoIds = staticData.postedVideoIds.slice(-500);
}
return $input.all();
